sources.content:
import { total } from './total.js';

test('total of empty array', () => {
  expect(total([])).toBe(0);
});

test('total of finite numbers', () => {
  expect(total([1, 2, 3])).toBe(6);
});

test('total of non-finite numbers', () => {
  expect(() => total([1, 2, Infinity])).toThrow();
});

test('total of non-numeric values', () => {
  expect(() => total([1, 'a', 3])).toThrow();
});
